def seed_troncons_and_setup_postgis(apps, schema_editor):
    TronconRoutier = apps.get_model('urgences', 'TronconRoutier')

    for item in CAP_BON_TRONCONS_SEED:
        coords = item["coordinates"]
        wkt_pts = ", ".join(f"{lng} {lat}" for lat, lng in coords)
        geom_wkt = f"LINESTRING({wkt_pts})"
        TronconRoutier.objects.update_or_create(
            street_id=item["street_id"],
            defaults={
                "street_name": item["street_name"],
                "zone": item["zone"],
                "road_type": item["road_type"],
                "base_speed_kmh": item["base_speed_kmh"],
                "length_km": item["length_km"],
                "proximity_sensitive": item["proximity_sensitive"],
                "alternatives": item["alternatives"],
                "coordinates": coords,
                "geom_wkt": geom_wkt,
            },
        )

    if schema_editor.connection.vendor == 'postgresql':
        with schema_editor.connection.cursor() as cursor:
            cursor.execute("CREATE EXTENSION IF NOT EXISTS postgis;")
            # LineString geometry + GIST index sur troncon_routier
            cursor.execute(
                "ALTER TABLE troncon_routier ADD COLUMN IF NOT EXISTS geom geometry(LineString, 4326);"
            )
            cursor.execute(
                "UPDATE troncon_routier SET geom = ST_SetSRID(ST_GeomFromText(geom_wkt), 4326) WHERE geom_wkt <> '';"
            )
            cursor.execute(
                "CREATE INDEX IF NOT EXISTS troncon_routier_geom_gist ON troncon_routier USING GIST (geom);"
            )
            # Point geometry + GIST indexes sur chantiers, alertes et signalements
            for tbl, idx_name in [
                ("urgences_chantier", "urgences_chantier_geom_gist"),
                ("urgences_alerteaccident", "urgences_alerte_geom_gist"),
                ("signalements_signalement", "signalements_sig_geom_gist"),
            ]:
                cursor.execute(
                    f"ALTER TABLE {tbl} ADD COLUMN IF NOT EXISTS geom geometry(Point, 4326);"
                )
                cursor.execute(
                    f"UPDATE {tbl} SET geom = ST_SetSRID(ST_MakePoint(longitude, latitude), 4326) WHERE latitude IS NOT NULL AND longitude IS NOT NULL;"
                )
                cursor.execute(
                    f"CREATE INDEX IF NOT EXISTS {idx_name} ON {tbl} USING GIST (geom);"
                )


